export type CalculatorInput = {
  monthlySearches: number;
  currentCtr: number;
  targetCtr: number;
};

export function calculateAdditionalClicks({
  monthlySearches,
  currentCtr,
  targetCtr,
}: CalculatorInput) {
  const ctrDelta = Math.max(targetCtr - currentCtr, 0) / 100;
  return Math.round(monthlySearches * ctrDelta);
}
